import React, { useState, useEffect } from "react";
import axios from "axios";
import "./App.css";

const operations = {
  gray: { url: "/process/gray" },
  binary: { url: "/process/binary", params: ["threshold"] },
  rotate: { url: "/process/rotate", params: ["angle"] },
  crop: { url: "/process/crop", params: ["x", "y", "width", "height"] },
  zoom: { url: "/process/zoom", params: ["scale"] },
  color: { url: "/process/color", params: ["mode"] },
  histogram: { url: "/process/histogram" },
  contrast: { url: "/process/contrast", params: ["factor"] },
  median: { url: "/process/median", params: ["kernel_size"] },
  double_threshold: { url: "/process/double_threshold", params: ["low_thresh", "high_thresh"] },
  edge: { url: "/process/edge", params: ["threshold1", "threshold2"] },
  salt_pepper: { url: "/process/noise", params: ["amount"] },
  denoise: { url: "/process/denoise", params: ["filter_type", "kernel_size"] },
  motion: { url: "/process/motion", params: ["kernel_size"] },
  morphology: { url: "/process/morphology", params: ["morph_op", "kernel_size"] },
  arithmetic: { url: "/process/arithmetic", params: ["arithmetic_op"] },
};

const defaultParamsByOperation = {
  binary: { threshold: 128 },
  double_threshold: { low_thresh: 50, high_thresh: 150 },
  edge: { threshold1: 50, threshold2: 150 },
  crop: { x: 2, y: 2, width: 0, height: 0 },
  zoom: { scale: 1.2 },
  rotate: { angle: 45 },
  contrast: { factor: 0.5 },
  median: { kernel_size: 3 },
  denoise: { filter_type: "median", kernel_size: 3 },
  motion: { kernel_size: 5 },
  salt_pepper: { amount: 0.05 },
  morphology: { morph_op: "dilate", kernel_size: 3 },
  arithmetic: { arithmetic_op: "subtract" },
  color: { mode: "hsv" },
};

function App() {
  const [selectedOperation, setSelectedOperation] = useState("gray");
  const [file, setFile] = useState(null);
  const [secondFile, setSecondFile] = useState(null);
  const [params, setParams] = useState(defaultParamsByOperation["gray"] || {});
  const [resultUrl, setResultUrl] = useState(null);

  useEffect(() => {
    setParams(defaultParamsByOperation[selectedOperation] || {});
  }, [selectedOperation]);

  const handleParamChange = (e) => {
    setParams({ ...params, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    const operation = operations[selectedOperation];
    const formData = new FormData();
    formData.append("file", file);

    if (selectedOperation === "arithmetic") {
      formData.append("file2", secondFile);
    }

    if (operation.params) {
      operation.params.forEach((param) => {
        formData.append(param, params[param] || "");
      });
    }

    try {
      const response = await axios.post(
        `http://localhost:8001${operation.url}`,
        formData,
        { responseType: "blob" }
      );
      setResultUrl(URL.createObjectURL(response.data));
    } catch (err) {
      console.error("İşlem sırasında hata oluştu:", err);
    }
  };

  const renderParamInputs = () => {
    const op = selectedOperation;
    const keys = operations[op]?.params || [];

    return (
      <div className="params">
        {keys.map((key) => {
          if (key === "mode") {
            return (
              <div className="param-field" key={key}>
                <label htmlFor={key}>Renk Uzayı:</label>
                <select
                  name={key}
                  value={params[key]}
                  onChange={handleParamChange}
                >
                  <option value="hsv">HSV</option>
                  <option value="ycbcr">YCbCr</option>
                  <option value="lab">Lab</option>
                </select>
              </div>
            );
          }
          if (key === "arithmetic_op") {
            return (
              <div className="param-field" key={key}>
                <label htmlFor={key}>Aritmetik İşlem:</label>
                <select
                  name={key}
                  value={params[key]}
                  onChange={handleParamChange}
                >
                  <option value="subtract">Çıkarma</option>
                  <option value="multiply">Çarpma</option>
                </select>
              </div>
            );
          }
          return (
            <div className="param-field" key={key}>
              <label htmlFor={key}>{key} değeri:</label>
              <input
                type="text"
                name={key}
                value={params[key] || ""}
                onChange={handleParamChange}
              />
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="app-container">
      <h1>Görüntü İşleme Arayüzü</h1>
      <div className="controls">
        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        {selectedOperation === "arithmetic" && (
          <input
            type="file"
            onChange={(e) => setSecondFile(e.target.files[0])}
          />
        )}
        <select
          value={selectedOperation}
          onChange={(e) => setSelectedOperation(e.target.value)}
        >
          {Object.entries(operations).map(([key, val]) => (
            <option key={key} value={key}>
              {key.replace("_", " ").toUpperCase()}
            </option>
          ))}
        </select>
        {renderParamInputs()}
        <button onClick={handleSubmit}>Uygula</button>
      </div>
      <div className="image-display">
        {file && <img src={URL.createObjectURL(file)} alt="Orijinal" />}
        {selectedOperation === "arithmetic" && secondFile && (
          <img src={URL.createObjectURL(secondFile)} alt="İkinci Görsel" />
        )}
        {resultUrl && <img src={resultUrl} alt="Sonuç" />}
      </div>
    </div>
  );
}

export default App;
